import pickle
import time

class SessionCache:
    def __init__(self, ttl=3600):
        self.cache = {}
        self.ttl = ttl

    def set(self, session_id, user_data):
        """Store serialized user session in cache."""
        serialized = pickle.dumps(user_data)
        self.cache[session_id] = {
            'data': serialized,
            'timestamp': time.time()
        }

    def get(self, session_id):
        """Retrieve and deserialize user session."""
        if session_id not in self.cache:
            return None

        entry = self.cache[session_id]
        if time.time() - entry['timestamp'] > self.ttl:
            del self.cache[session_id]
            return None

        # Deserialize the pickled object
        return pickle.loads(entry['data'])

    def clear_expired(self):
        """Remove expired sessions."""
        current_time = time.time()
        expired = [sid for sid, entry in self.cache.items() 
                   if current_time - entry['timestamp'] > self.ttl]
        for sid in expired:
            del self.cache[sid]
